using namespace std;

const double PI = acos(-1.0);

class InputReader {
public:
    InputReader() {
        ios_base::sync_with_stdio(false);
        cin.tie(nullptr);
    }
    int nextInt() {
        int x;
        cin >> x;
        return x;
    }
};

class TaskG {
public:
    void solve(int testNumber, InputReader& in, ostream& out) {
        const int mod = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        vector<int> v(10, 0);
        for (int i = 0; i < k; ++i) {
            int x = in.nextInt();
            v[x] = 1;
        }
        vector<int> ans = {1};
        int p = n / 2;
        exponentiate(&ans, &v, p, mod);
        long long res = 0;
        for (int x : ans) {
            res = (res + (long long)x * x) % mod;
        }
        out << res << '\n';
    }

    static void exponentiate(vector<int>* ans, vector<int>* v, int p, int mod) {
        if (p == 0) return;
        if (p & 1) {
            ans = new vector<int>(multiplyMod(*ans, *v, mod));
        }
        v = new vector<int>(multiplyMod(*v, *v, mod));
        exponentiate(ans, v, p >> 1, mod);
    }

    static vector<int> multiplyMod(const vector<int>& a, const vector<int>& b, int mod) {
        int need = a.size() + b.size() - 1;
        int n = 1;
        while (n < need) n <<= 1;
        if (n < 2) n = 2;

        vector<double> aReal(n, 0), aImag(n, 0);
        for (size_t i = 0; i < a.size(); ++i) {
            int x = (a[i] % mod + mod) % mod;
            aReal[i] = x & ((1 << 15) - 1);
            aImag[i] = x >> 15;
        }
        fft(aReal, aImag, false);

        vector<double> bReal(n, 0), bImag(n, 0);
        for (size_t i = 0; i < b.size(); ++i) {
            int x = (b[i] % mod + mod) % mod;
            bReal[i] = x & ((1 << 15) - 1);
            bImag[i] = x >> 15;
        }
        fft(bReal, bImag, false);

        vector<double> faReal(n), faImag(n), fbReal(n), fbImag(n);
        for (int i = 0; i < n; ++i) {
            int j = (n - i) & (n - 1);

            double a1r = (aReal[i] + aReal[j]) / 2;
            double a1i = (aImaginary[i] - aImaginary[j]) / 2;
            double a2r = (aImaginary[i] + aImaginary[j]) / 2;
            double a2i = (aReal[j] - aReal[i]) / 2;

            double b1r = (bReal[i] + bReal[j]) / 2;
            double b1i = (bImaginary[i] - bImaginary[j]) / 2;
            double b2r = (bImaginary[i] + bImaginary[j]) / 2;
            double b2i = (bReal[j] - bReal[i]) / 2;

            faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            faImaginary[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

            fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            fbImaginary[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(faReal, faImaginary, true);
        fft(fbReal, fbImaginary, true);

        vector<int> res(need);
        for (int i = 0; i < need; ++i) {
            long long aa = (long long)(faReal[i] + 0.5);
            long long bb = (long long)(fbReal[i] + 0.5);
            long long cc = (long long)(faImaginary[i] + 0.5);
            res[i] = (int)((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return res;
    }

    static void fft(vector<double>& a, vector<double>& b, bool inverse) {
        int n = a.size();
        int shift = 0;
        int temp = n;
        while (temp % 2 == 0) {
            shift++;
            temp >>= 1;
        }
        vector<int> rev(n);
        for (int i = 1; i < n; ++i) {
            rev[i] = (rev[i >> 1] >> 1) + ((i & 1) ? n / 2 : 0);
        }
        for (int i = 1; i < n; ++i) {
            int j = rev[i];
            if (i < j) {
                swap(a[i], a[j]);
                swap(b[i], b[j]);
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            int halfLen = len >> 1;
            vector<double> cs(halfLen), sn(halfLen);
            for (int i = 0; i < halfLen; ++i) {
                double angle = 2 * PI * i / len * (inverse ? -1 : 1);
                cs[i] = cos(angle);
                sn[i] = sin(angle);
            }
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < halfLen; ++j) {
                    double wA = cs[j];
                    double wB = sn[j];
                    double uA = a[i + j];
                    double uB = b[i + j];
                    double vA = a[i + j + halfLen] * wA - b[i + j + halfLen] * wB;
                    double vB = a[i + j + halfLen] * wB + b[i + j + halfLen] * wA;
                    a[i + j] = uA + vA;
                    b[i + j] = uB + vB;
                    a[i + j + halfLen] = uA - vA;
                    b[i + j + halfLen] = uB - vB;
                }
            }
        }
        if (inverse) {
            for (int i = 0; i < n; ++i) {
                a[i] /= n;
                b[i] /= n;
            }
        }
    }
};

int main() {
    InputReader in;
    ostream& out = cout;
    TaskG solver;
    solver.solve(1, in, out);
    return 0;
}
